def contar(lista, x):
    if not lista:
        return 0
    return (1 if lista[0] == x else 0) + contar(lista[1:], x)

def invertir(capitales):
    resultado = {}
    for ciudad, pais in capitales.items():
        resultado.setdefault(pais, []).append(ciudad)
    for ciudades in resultado.values():
        ciudades.sort()
    return resultado

def edad_valida(texto):
    try:
        edad = int(texto)
    except ValueError:
        raise ValueError("no es un número")
    if not 0 <= edad <= 120:
        raise ValueError("fuera de rango")
    return edad
